package com.aistock.notification.alert;
import java.time.Clock;import org.springframework.context.annotation.*;import org.springframework.core.env.Environment;import org.springframework.cloud.client.discovery.DiscoveryClient;
@Configuration public class AlertBackgroundClientConfiguration {
 @Bean AlertRemoteHttp alertRemoteHttp(Environment env,DiscoveryClient discovery){return new AlertRemoteHttp(service->{String key="stock-market-service".equals(service)?"aistock.market.url":"aistock.user.url";String configured=env.getProperty(key);if(configured!=null&&!configured.isBlank())return configured;var instances=discovery.getInstances(service);if(instances.isEmpty())throw AlertRemoteHttp.unavailable();return instances.get(0).getUri().toString();},env.getProperty("aistock.internal.token",""));}
 @Bean AlertAccountClient alertAccountClient(AlertRemoteHttp http,Clock clock){return new AlertAccountClient(http,clock);}
 @Bean AlertEvidenceClient alertEvidenceClient(AlertRemoteHttp http,Clock clock,Environment env){return new AlertEvidenceClient(http,clock,env.getProperty("aistock.market.update-hour",Integer.class,20));}
 @Bean AlertMailAccountClient alertMailAccountClient(Environment env,DiscoveryClient discovery,Clock clock){return new AlertMailAccountClient(()->{String configured=env.getProperty("aistock.user.url");if(configured!=null&&!configured.isBlank())return configured;var instances=discovery.getInstances("stock-user-service");if(instances.isEmpty())throw AlertRemoteHttp.unavailable();return instances.get(0).getUri().toString();},env.getProperty("aistock.internal.token",""),clock);}
 @Bean com.aistock.notification.alertmail.AlertMailRepository alertMailRepository(org.springframework.jdbc.core.JdbcTemplate jdbc){return new com.aistock.notification.alertmail.AlertMailRepository(jdbc);}
 @Bean com.aistock.notification.alertmail.AlertMailOutbox alertMailOutbox(com.aistock.notification.alertmail.AlertMailRepository repo,Environment env){return new com.aistock.notification.alertmail.AlertMailOutbox(repo,env.getProperty("aistock.alert.mail-worker-enabled",Boolean.class,false),java.time.Duration.ofSeconds(env.getProperty("aistock.alert.mail-ttl-seconds",Long.class,86400L)));}}
